package codecard_test

import (
	"bytes"
	"errors"
	"strings"
	"testing"

	"github.com/wrouesnel/code-card/pkg/codecard"
)

// Expected tables were generated by the original Python implementation.
func TestSemiRandomTableMatchesPython(t *testing.T) {
	cases := []struct {
		salt, code, keyword string
		rows                string
	}{
		{"1337code8Ackz0rs", "1234", "word", "A 0,B 1,C 2,D 4,E 4,F 5,G 6,H 7,I 8,J 9,K 0,L 1,M 2,N 3,O 2,P 5,Q 6,R 3,S 8,T 9,U 4,V 6,W 1,X 0,Y 9,Z 3"},
		{"1337code8Ackz0rs", "12345", "Hello", "A 0 4,B 1 2,C 2 0,D 3 1,E 2 4,F 5 5,G 6 8,H 1 2,I 8 5,J 9 6,K 0 2,L 3 4,M 2 9,N 3 2,O 5 4,P 5 8,Q 6 9,R 7 0,S 8 7,T 9 6,U 2 3,V 2 1,W 3 1,X 8 9,Y 7 3,Z 7 3"},
		{"another-salt-value-x", "9876", "bookkeeper", "A 0 6 7,B 9 5 4,C 2 7 3,D 3 0 0,E 4 7 2,F 5 5 3,G 6 5 7,H 7 8 5,I 8 4 4,J 9 5 6,K 6 9 9,L 1 8 9,M 2 8 6,N 3 0 3,O 8 7 5,P 5 2 6,Q 6 6 7,R 7 6 5,S 8 0 7,T 9 2 6,U 3 9 1,V 4 7 5,W 0 1 7,X 2 5 7,Y 9 6 8,Z 6 9 7"},
		{"1337code8Ackz0rs", "000", "aaa", "A 0 0 0,B 1 5 7,C 2 4 7,D 3 7 5,E 4 8 6,F 5 8 6,G 6 4 9,H 7 8 7,I 8 7 3,J 9 3 1,K 0 3 3,L 1 9 1,M 2 0 1,N 3 8 1,O 4 7 1,P 5 1 2,Q 6 8 2,R 7 9 7,S 8 4 7,T 9 4 3,U 3 8 8,V 6 9 7,W 1 9 7,X 7 8 9,Y 7 5 8,Z 3 8 6"},
		{"1337code8Ackz0rs", "42", "Zyzzyva", "A 0 3 1,B 1 4 0,C 2 6 5,D 3 6 1,E 4 4 6,F 5 7 4,G 6 8 5,H 7 8 2,I 8 4 8,J 9 3 1,K 0 9 1,L 1 5 5,M 2 0 2,N 3 8 9,O 4 3 5,P 5 2 5,Q 6 9 6,R 7 4 4,S 8 7 0,T 9 5 1,U 0 6 7,V 0 2 8,W 0 7 7,X 4 7 6,Y 2 3 5,Z 4 3 5"},
	}

	for _, tc := range cases {
		t.Run(tc.keyword, func(t *testing.T) {
			table, err := codecard.SemiRandomTable(tc.salt, tc.code, tc.keyword)
			if err != nil {
				t.Fatal(err)
			}
			if got := strings.Join(table.Rows(), ","); got != tc.rows {
				t.Errorf("table mismatch:\n got: %s\nwant: %s", got, tc.rows)
			}
		})
	}
}

func TestSemiRandomTableDecodes(t *testing.T) {
	const code, keyword = "314159", "papaya"
	table, err := codecard.SemiRandomTable("a-sufficiently-long-salt", code, keyword)
	if err != nil {
		t.Fatal(err)
	}
	seen := map[byte]int{}
	var decoded []byte
	for _, letter := range []byte(strings.ToUpper(keyword)) {
		decoded = append(decoded, table[letter-'A'][seen[letter]])
		seen[letter]++
	}
	if string(decoded) != code {
		t.Errorf("decoded %q, want %q", decoded, code)
	}
}

func TestSemiRandomTableErrors(t *testing.T) {
	const salt = "1337code8Ackz0rs"
	cases := []struct {
		name, salt, code, keyword string
		want                      error
	}{
		{"short salt", "short", "1234", "word", codecard.ErrSaltTooShort},
		{"short keyword", salt, "12345", "word", codecard.ErrKeywordTooShort},
		{"repeats", salt, "1234", "aaaa", codecard.ErrTooManyRepeats},
		{"empty keyword", salt, "", "", codecard.ErrInvalidKeyword},
		{"non-letter keyword", salt, "1234", "w0rd", codecard.ErrInvalidKeyword},
		{"non-digit code", salt, "12a4", "word", codecard.ErrInvalidCode},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := codecard.SemiRandomTable(tc.salt, tc.code, tc.keyword); !errors.Is(err, tc.want) {
				t.Errorf("got error %v, want %v", err, tc.want)
			}
		})
	}
}

func TestRandomTable(t *testing.T) {
	table := codecard.RandomTable()
	counts := map[byte]int{}
	for _, values := range table {
		if len(values) != 1 || values[0] < '0' || values[0] > '9' {
			t.Fatalf("invalid table entry %q", values)
		}
		counts[values[0]]++
	}
	// Every digit is used at least twice, since 26 letters cover the 10 digits twice over.
	for digit := byte('0'); digit <= '9'; digit++ {
		if counts[digit] < 2 {
			t.Errorf("digit %c used %d times, want at least 2", digit, counts[digit])
		}
	}
}

func TestRender(t *testing.T) {
	table := codecard.RandomTable()
	var buf bytes.Buffer
	if err := codecard.Render(&buf, &table, codecard.RenderOptions{Title: "Test", DebugGrid: true}); err != nil {
		t.Fatal(err)
	}
	if !bytes.HasPrefix(buf.Bytes(), []byte("%PDF-")) {
		t.Errorf("output is not a PDF: %q", buf.Bytes()[:min(16, buf.Len())])
	}
}
